    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (2, 3, 6)]
    color = grid[points[0][0]][points[0][1]]
    out = [row[:] for row in grid]
    if line_row is not None:
        axis = int(sum(r for r, c in points) / len(points) + 0.5)
        out[axis] = [8] * w
        if min(r for r, c in points) > line_row:
            dr = line_row + 1 - min(r for r, c in points)
        else:
            dr = line_row - 1 - max(r for r, c in points)
        for r, c in points:
            out[r][c] = grid[r][c]
        shifted = [(r + dr, c) for r, c in points]
    else:
        axis = int(sum(c for r, c in points) / len(points) + 0.5)
        for r in range(h):
            out[r][axis] = 8
        if min(c for r, c in points) > line_col:
            dc = line_col + 1 - min(c for r, c in points)
        else:
            dc = line_col - 1 - max(c for r, c in points)
        shifted = [(r, c + dc) for r, c in points]
    for r, c in points:
        out[r][c] = 3 if grid[r][c] == color else out[r][c]
    for r, c in shifted:
        out[r][c] = color
    return out
